package algorithms.graphs;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class StronglyConnectedComponents {
public static List<List<Integer>> tarjanScc(List<List<Integer>> g){int[] index=new int[g.size()],low=new int[g.size()],counter={0};Arrays.fill(index,-1);boolean[] on=new boolean[g.size()];Deque<Integer> st=new ArrayDeque<>();List<List<Integer>> o=new ArrayList<>();for(int i=0;i<g.size();i++)if(index[i]==-1)connect(g,i,index,low,counter,on,st,o);return o;}private static void connect(List<List<Integer>> g,int v,int[] idx,int[] low,int[] counter,boolean[] on,Deque<Integer> st,List<List<Integer>> o){idx[v]=low[v]=counter[0]++;st.push(v);on[v]=true;for(int n:g.get(v)){if(idx[n]==-1){connect(g,n,idx,low,counter,on,st,o);low[v]=Math.min(low[v],low[n]);}else if(on[n])low[v]=Math.min(low[v],idx[n]);}if(low[v]!=idx[v])return;List<Integer> c=new ArrayList<>();int n;do{n=st.pop();on[n]=false;c.add(n);}while(n!=v);o.add(algorithms.sorting.MergeSort.mergeSort(c));}public static List<List<Integer>> kosarajuScc(List<List<Integer>> g){List<List<Integer>> r=new ArrayList<>();for(int i=0;i<g.size();i++)r.add(new ArrayList<>());for(int i=0;i<g.size();i++)for(int n:g.get(i))r.get(n).add(i);boolean[] v=new boolean[g.size()];List<Integer> order=new ArrayList<>();for(int i=0;i<g.size();i++)if(!v[i])finish(g,i,v,order);Arrays.fill(v,false);Collections.reverse(order);List<List<Integer>> o=new ArrayList<>();for(int x:order)if(!v[x]){List<Integer> c=new ArrayList<>();collect(r,x,v,c);o.add(algorithms.sorting.MergeSort.mergeSort(c));}return o;}private static void finish(List<List<Integer>> g,int x,boolean[] v,List<Integer> o){v[x]=true;for(int n:g.get(x))if(!v[n])finish(g,n,v,o);o.add(x);}private static void collect(List<List<Integer>> g,int x,boolean[] v,List<Integer> o){v[x]=true;o.add(x);for(int n:g.get(x))if(!v[n])collect(g,n,v,o);}
}
